package solution

import "context"

// First runs each fn concurrently and returns the first successful result.
// If ctx ends before any success, it returns ctx.Err().
func First(ctx context.Context, fns []func(context.Context) (int, error)) (int, error) {
	results := make(chan int, len(fns)) // buffered so winners never block
	for _, fn := range fns {
		fn := fn // capture per iteration (safe on any Go version)
		go func() {
			if v, err := fn(ctx); err == nil {
				select {
				case results <- v: // report success
				case <-ctx.Done(): // give up if already cancelled
				}
			}
		}()
	}
	select {
	case v := <-results: // first success wins
		return v, nil
	case <-ctx.Done(): // nobody succeeded in time
		return 0, ctx.Err()
	}
}

