func search(ctx context.Context) int {
	out := make(chan int, 1) // buffered: the send always succeeds
	go func() {
		out <- slowQuery() // never blocks now, so the goroutine exits
	}()
	select {
	case v := <-out:
		return v
	case <-ctx.Done():
		return -1 // goroutine still finishes and the buffered send completes
	}
}

import (
	"context"
	"time"
)

// DoWithRetry retries fn up to attempts times, aborting on ctx cancellation.
func DoWithRetry(ctx context.Context, attempts int, fn func() error) error {
	var err error
	for i := 0; i < attempts; i++ {
		if err = fn(); err == nil {
			return nil // success
		}
		if i == attempts-1 {
			break // last attempt failed; don't wait
		}
		select {
		case <-ctx.Done(): // cancellation beats the backoff
			return ctx.Err()
		case <-time.After(100 * time.Millisecond): // backoff before retry
		}
	}
	return err // last error after exhausting attempts
}
